sys_script_include.script:
/**
 * AppForgeSchemaFieldRegistry
 * Authoritative Server-Side Service for managing Schema Field metadata definitions.
 */
var AppForgeSchemaFieldRegistry = Class.create();
AppForgeSchemaFieldRegistry._store = {};

AppForgeSchemaFieldRegistry.prototype = {
    initialize: function() {
        'use strict';
        this.LOG_PREFIX = '[AppForgeSchemaFieldRegistry] ';
        this.TABLE_NAME = 'x_appforge_schema_field';
        this.SUPPORTED_TYPES = [
            'string', 'integer', 'decimal', 'boolean',
            'date', 'datetime', 'reference', 'choice',
            'currency', 'journal', 'html'
        ];
        if (!AppForgeSchemaFieldRegistry._store) {
            AppForgeSchemaFieldRegistry._store = {};
        }
        this._store = AppForgeSchemaFieldRegistry._store;
    },

    create: function(fieldData) {
        'use strict';
        var valResult = this.validate(fieldData, false);
        if (!valResult.valid) {
            return { success: false, error: valResult.error };
        }

        var fldId = fieldData.field_id || fieldData.name;
        var sysId = 'sys_id_' + fldId;
        var fldRecord = {
            sys_id: sysId,
            field_id: fldId,
            name: fieldData.name,
            label: fieldData.label || fieldData.name,
            schema: fieldData.schema,
            internal_type: fieldData.internal_type,
            max_length: fieldData.max_length || 40,
            mandatory: fieldData.mandatory !== undefined ? fieldData.mandatory : false,
            unique: fieldData.unique !== undefined ? fieldData.unique : false,
            default_value: fieldData.default_value || '',
            reference_table: fieldData.reference_table || '',
            sequence: fieldData.sequence || 10,
            active: fieldData.active !== undefined ? fieldData.active : true
        };

        this._store[sysId] = fldRecord;
        this._store[fieldData.name + '_' + fieldData.schema] = fldRecord;
        this._store[fldId + '_' + fieldData.schema] = fldRecord;

        try {
            var gr = new GlideRecordSecure(this.TABLE_NAME);
            gr.initialize();
            gr.setValue('field_id', fldId);
            gr.setValue('name', fieldData.name);
            gr.setValue('label', fldRecord.label);
            gr.setValue('schema', fieldData.schema);
            gr.setValue('internal_type', fieldData.internal_type);
            gr.setValue('max_length', fldRecord.max_length);
            gr.setValue('mandatory', fldRecord.mandatory);
            gr.setValue('unique', fldRecord.unique);
            gr.setValue('default_value', fldRecord.default_value);
            gr.setValue('reference_table', fldRecord.reference_table);
            gr.setValue('sequence', fldRecord.sequence);
            gr.setValue('active', fldRecord.active);

            var insertedId = gr.insert();
            if (insertedId) {
                sysId = insertedId;
                fldRecord.sys_id = sysId;
                this._store[sysId] = fldRecord;
            }
        } catch (ex) {}

        gs.info(this.LOG_PREFIX + 'Field created: ' + fieldData.name + ' (' + fieldData.internal_type + ') [Sys ID: ' + sysId + ']');
        return { success: true, sys_id: sysId, field_id: fldId, name: fieldData.name };
    },

    get: function(sysId) {
        'use strict';
        if (!sysId) return null;
        if (this._store[sysId]) return this._store[sysId];
        try {
            var gr = new GlideRecordSecure(this.TABLE_NAME);
            if (gr.get(sysId)) {
                var mapped = this._mapRecord(gr);
                this._store[sysId] = mapped;
                return mapped;
            }
        } catch (ex) {}
        return null;
    },

    exists: function(schemaSysId, fieldName) {
        'use strict';
        if (!schemaSysId || !fieldName) return false;
        if (this._store[fieldName + '_' + schemaSysId]) return true;
        try {
            var gr = new GlideRecordSecure(this.TABLE_NAME);
            gr.addQuery('schema', schemaSysId);
            gr.addQuery('name', fieldName);
            gr.query();
            return gr.hasNext();
        } catch (ex) {
            return false;
        }
    },

    validate: function(fieldData, isUpdate) {
        'use strict';
        if (!fieldData) return { valid: false, error: 'Field data is required' };
        if (!isUpdate) {
            if (!fieldData.schema) return { valid: false, error: 'schema is mandatory for field' };
            if (!fieldData.name) return { valid: false, error: 'name is mandatory' };
            if (!fieldData.internal_type) return { valid: false, error: 'internal_type is mandatory' };

            if (this.SUPPORTED_TYPES.indexOf(fieldData.internal_type) === -1) {
                return { valid: false, error: 'Unsupported internal_type: ' + fieldData.internal_type };
            }

            if (this.exists(fieldData.schema, fieldData.name)) {
                return { valid: false, error: 'Field (' + fieldData.name + ') already exists within this schema' };
            }
        }
        return { valid: true };
    },

    list: function(schemaSysId) {
        'use strict';
        var results = [];
        try {
            var gr = new GlideRecordSecure(this.TABLE_NAME);
            if (schemaSysId) gr.addQuery('schema', schemaSysId);
            gr.query();
            while (gr.next()) {
                results.push(this._mapRecord(gr));
            }
        } catch (ex) {}

        if (results.length === 0) {
            var seen = {};
            for (var k in this._store) {
                if (this._store.hasOwnProperty(k) && this._store[k].sys_id) {
                    var rec = this._store[k];
                    if (!seen[rec.sys_id]) {
                        seen[rec.sys_id] = true;
                        if (!schemaSysId || rec.schema === schemaSysId) {
                            results.push(rec);
                        }
                    }
                }
            }
        }
        return results;
    },

    _mapRecord: function(gr) {
        'use strict';
        return {
            sys_id: gr.getUniqueValue(),
            field_id: gr.getValue('field_id'),
            name: gr.getValue('name'),
            label: gr.getValue('label'),
            schema: gr.getValue('schema'),
            internal_type: gr.getValue('internal_type'),
            max_length: parseInt(gr.getValue('max_length'), 10) || 40,
            mandatory: gr.getValue('mandatory') === '1' || gr.getValue('mandatory') === true,
            unique: gr.getValue('unique') === '1' || gr.getValue('unique') === true,
            default_value: gr.getValue('default_value'),
            reference_table: gr.getValue('reference_table'),
            sequence: parseInt(gr.getValue('sequence'), 10) || 10,
            active: gr.getValue('active') === '1' || gr.getValue('active') === true
        };
    },

    type: 'AppForgeSchemaFieldRegistry'
};
